[CmdletBinding()]
param([string]$VictimVmName='XDR-Victim-Sprint18',[string]$CredentialPath='D:\VMs\XDR-Victim-Sprint18\victim-credential.xml',[string]$QualificationRoot='C:\Sprint22Qualification',[int]$TimeoutSeconds=300)
$ErrorActionPreference='Stop';$root=Resolve-Path (Join-Path $PSScriptRoot '../..');Set-Location $root
$settings=@{};Get-Content .env|Where-Object{$_-match '^\s*([^#=\s]+)=(.*)$'}|ForEach-Object{$settings[$matches[1]]=$matches[2].Trim().Trim('"').Trim("'")}
$login=Invoke-RestMethod -Method Post http://127.0.0.1:8080/api/v1/auth/token -ContentType application/json -Body (@{username=$settings.PLATFORM_BOOTSTRAP_USER;password=$settings.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json -Compress);$admin=@{Authorization="Bearer $($login.access_token)"}
function B64([byte[]]$v){[Convert]::ToBase64String($v).TrimEnd('=').Replace('+','-').Replace('/','_')};function Jwt{$now=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$h=B64([Text.Encoding]::UTF8.GetBytes('{"alg":"HS256","typ":"JWT"}'));$b=B64([Text.Encoding]::UTF8.GetBytes((@{iss='security-platform';aud='security-platform-api';sub='sprint22-separated-approver';tid=$settings.PLATFORM_BOOTSTRAP_TENANT_ID;per=@('platform:admin');pty='user';iat=$now;exp=$now+7200;jti=[guid]::NewGuid().ToString('N')}|ConvertTo-Json -Compress)));$m=[Security.Cryptography.HMACSHA256]::new([Text.Encoding]::UTF8.GetBytes($settings.PLATFORM_JWT_SIGNING_KEY));try{$s=B64($m.ComputeHash([Text.Encoding]::ASCII.GetBytes("$h.$b")))}finally{$m.Dispose()};@{Authorization="Bearer $h.$b.$s"}};$approver=Jwt
function Api([string]$method,[string]$path,$headers=$admin,$body=$null){$a=@{Method=$method;Uri="http://127.0.0.1:8080$path";Headers=$headers;DisableKeepAlive=$true};if($null-ne$body){$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($body|ConvertTo-Json -Depth 80 -Compress))};try{(Invoke-RestMethod @a).data}catch{$d=$_.ErrorDetails.Message;throw "$method $path failed: $d"}}
function Session{$c=Import-Clixml $CredentialPath;New-PSSession -VMName $VictimVmName -Credential $c};function Victim([scriptblock]$script,[object[]]$arguments=@()){$s=Session;try{Invoke-Command $s $script -ArgumentList $arguments}finally{Remove-PSSession $s}};function Stop-Agent{Victim{Get-Process Platform.Agent -ErrorAction SilentlyContinue|Stop-Process -Force;Start-Sleep 1}|Out-Null};function Start-Agent{Victim{param($q)$env:PLATFORM_CONTROL_PLANE_URL='https://gateway:8443';$env:PLATFORM_AGENT_DATA="$q\runtime-data";$env:PLATFORM_CA_CERT_PATH='C:\Sprint19Qualification\ca.crt';$env:PLATFORM_ENVIRONMENT='production';(Start-Process "$q\agent\Platform.Agent.exe" -PassThru -WindowStyle Hidden -RedirectStandardOutput "$q\agent.log" -RedirectStandardError "$q\agent-error.log").Id}@($QualificationRoot)}
function Wait-Collection([guid]$id){$end=[DateTimeOffset]::UtcNow.AddSeconds($TimeoutSeconds);do{Start-Sleep -Milliseconds 300;$x=Api GET "/api/v1/forensic-collections/$id"}while($x.state-notin@('Succeeded','Partial','Failed','Cancelled','CancelledWithEvidence','Expired')-and[DateTimeOffset]::UtcNow-lt$end);$x};function Create-Collection([guid]$endpoint,[string]$profile,[object[]]$items,[string]$reason){$x=Api POST '/api/v1/forensic-collections' $admin @{endpointId=$endpoint;profileId=$profile;profileVersion=1;requestedArtifacts=$items;reason=$reason;expiresInSeconds=900;policyVersion='forensic-collection-policy.v1'};if($x.approvalState-eq'Pending'){$x=Api POST "/api/v1/forensic-collections/$($x.collectionId):approve" $approver @{parameterHash=$x.parameterHash;reason='Separated exact-scope approval'}};$x};function Artifact([string]$id,$f){@{requestId=$id;artifactType='File';fileTarget=@{fileEntityId=$f.fileEntityId;nativeIdentity=$f.nativeIdentity;canonicalPath=$f.currentPath;expectedSize=$f.metadata.size;expectedSha256=$f.hash.sha256;observedAt=$f.lastObserved};maximumItems=1;maximumBytes=[long]$f.metadata.size}}
$endpoint=(Api GET '/api/v1/endpoints?pageSize=100').items|Where-Object platform -eq windows|Sort-Object lastSeenAt -Descending|Select-Object -First 1;$all=(Api GET "/api/v1/files?endpointId=$($endpoint.id)&pageSize=200").items|Where-Object{$_.currentPath-like'C:\Sprint22Fixtures\*'-and$_.nativeIdentity.volumeId-and$_.nativeIdentity.fileId};$stable=$all|Where-Object currentPath -like '*\stable-fcde2b6f*'|Select-Object -First 1;$unicode=$all|Where-Object currentPath -like '*\evidence-*-fcde2b6f*'|Select-Object -First 1;$changing=$all|Where-Object currentPath -like '*\changing-fcde2b6f*'|Select-Object -First 1;if(!$stable-or!$unicode-or!$changing){throw 'Authoritative controlled Profile D entities unavailable.'}
$prior=Get-Content artifacts/sprint22-windows-forensic-collection.json -Raw|ConvertFrom-Json;$d=$prior.profiles.D.collection;$profileD=$prior.profiles.D.status-eq'PASS'
Stop-Agent;$partial=Create-Collection $endpoint.id 'file-evidence' @((Artifact missing $stable)) 'Profile E missing-after-approval yields truthful partial';Victim{param($p)Move-Item -LiteralPath $p -Destination ($p+'.gone') -Force}@($stable.currentPath)|Out-Null;$agentPid=Start-Agent;$partial=Wait-Collection $partial.collectionId
$cancelItems=@(@{requestId='first';artifactType='SystemInformation';maximumItems=1;maximumBytes=262144},@{requestId='evtx';artifactType='WindowsEventLog';source='Security';maximumItems=1;maximumBytes=8388608;maximumRecords=10000;lookbackMinutes=43200});$cancel=Create-Collection $endpoint.id 'endpoint-investigation' $cancelItems 'Profile E controlled cancellation with evidence';$end=[DateTimeOffset]::UtcNow.AddSeconds(30);do{Start-Sleep -Milliseconds 50;$current=Api GET "/api/v1/forensic-collections/$($cancel.collectionId)"}while($current.state-ne'Running'-and[DateTimeOffset]::UtcNow-lt$end);if($current.state-eq'Running'){Api POST "/api/v1/forensic-collections/$($cancel.collectionId):cancel" $admin @{reason='Controlled cancellation'}|Out-Null};$cancel=Wait-Collection $cancel.collectionId;$profileE=$partial.state-eq'Partial'-and$partial.result.failedItems-ge1-and$cancel.state-in@('Cancelled','CancelledWithEvidence')-and$cancel.result.cancellationObserved
$quick=@(@{requestId='system';artifactType='SystemInformation';maximumItems=1;maximumBytes=262144},@{requestId='processes';artifactType='ProcessInventory';maximumItems=32;maximumBytes=524288},@{requestId='users';artifactType='UserSessionInventory';maximumItems=32;maximumBytes=262144},@{requestId='services';artifactType='ServiceInventory';maximumItems=32;maximumBytes=524288},@{requestId='tasks';artifactType='ScheduledTaskInventory';maximumItems=32;maximumBytes=524288},@{requestId='network';artifactType='NetworkState';maximumItems=32;maximumBytes=524288});Stop-Agent;$offline=Create-Collection $endpoint.id 'quick-triage' $quick 'Profile F offline queue and restart replay';docker compose --env-file .env -f deployment/docker-compose.yml restart gateway|Out-Null;$end=[DateTimeOffset]::UtcNow.AddSeconds(120);do{Start-Sleep 2;try{$ready=(Invoke-WebRequest http://127.0.0.1:8080/health/ready -UseBasicParsing).StatusCode-eq200}catch{$ready=$false}}while(!$ready-and[DateTimeOffset]::UtcNow-lt$end);$agentPid=Start-Agent;$f=Wait-Collection $offline.collectionId;$hash=$f.result.manifestHash;Stop-Agent;$agentPid=Start-Agent;Start-Sleep 5;$replay=Api GET "/api/v1/forensic-collections/$($f.collectionId)";$profileF=$ready-and$f.state-eq'Succeeded'-and$replay.result.manifestHash-eq$hash
$collections=(Api GET '/api/v1/forensic-collections').items;$a=$collections|Where-Object{$_.profileId-eq'quick-triage'-and$_.state-eq'Succeeded'}|Sort-Object completedAt -Descending|Select-Object -First 1;$b=$collections|Where-Object{$_.profileId-eq'windows-event-evidence'-and$_.state-eq'Succeeded'}|Sort-Object completedAt -Descending|Select-Object -First 1;$c=$collections|Where-Object{$_.profileId-eq'registry-triage'-and$_.state-eq'Succeeded'}|Sort-Object completedAt -Descending|Select-Object -First 1;$profileA=[bool]$a;$profileB=[bool]$b;$profileC=[bool]$c
$queue=[long](docker exec deployment-postgres-1 psql -U platform -d platform -Atc "select count(*) from platform.response_actions where state not in ('Succeeded','Failed','TimedOut','Cancelled','Expired','Rejected');");$outbox=((docker exec deployment-postgres-1 psql -U platform -d platform -Atc "select count(*) filter(where published_at is null and failed_at is null)||'|'||count(*) filter(where failed_at is not null) from platform.outbox;").Trim()).Split('|')|ForEach-Object{[long]$_};$report=[ordered]@{schemaVersion='sprint22-windows-forensic-collection.v1';executedAt=[DateTimeOffset]::UtcNow;victim=@{vm=$VictimVmName;endpoint=$endpoint.id;agentPid=$agentPid};profiles=@{A=@{status=if($profileA){'PASS'}else{'FAIL'};collection=$a};B=@{status=if($profileB){'PASS'}else{'FAIL'};collection=$b};C=@{status=if($profileC){'PASS'}else{'FAIL'};collection=$c};D=@{status=if($profileD){'PASS'}else{'FAIL'};collection=$d};E=@{status=if($profileE){'PASS'}else{'FAIL'};partial=$partial;cancellation=$cancel};F=@{status=if($profileF){'PASS'}else{'FAIL'};collection=$f;backendRestart=$ready;replayHashStable=$replay.result.manifestHash-eq$hash}};queues=@{response=$queue;outboxPending=$outbox[0];outboxFailed=$outbox[1]};result=if($profileA-and$profileB-and$profileC-and$profileD-and$profileE-and$profileF-and$queue-eq0-and$outbox[0]-eq0-and$outbox[1]-eq0){'PASS'}else{'FAIL'}};$report|ConvertTo-Json -Depth 100|Set-Content artifacts/sprint22-windows-forensic-collection.json -Encoding utf8;$report|ConvertTo-Json -Depth 8;if($report.result-ne'PASS'){exit 1}
